// One-time migration: bring an old single-slot save (from before this update) into Slot 1,
// so existing progress isn't lost. Never overwrites an existing Slot 1.
function migrateLegacySaveIfNeeded(){
  try{
    const legacy = localStorage.getItem(LEGACY_SAVE_KEY);
    if(legacy && !localStorage.getItem(slotKey(1))){
      localStorage.setItem(slotKey(1), legacy);
      if(!localStorage.getItem(LAST_SLOT_KEY)) localStorage.setItem(LAST_SLOT_KEY, '1');
    }
  }catch(e){}
}

// Copies parsed save data (p) into the live `state` object. Does NOT touch the world/player -
// callers rebuild the world and restore position themselves afterwards.
function applyLoadedStateObject(p){
  state.money = p.money||0;
  state.pickaxeTier = p.pickaxeTier||0;
  state.bagTier = p.bagTier||0;
  state.investmentTier = p.investmentTier||0;
  state.droneCountTier = p.droneCountTier||0;
  state.droneSpeedTier = p.droneSpeedTier||0;
  state.droneCapTier = p.droneCapTier||0;
  state.efficiencyTier = p.efficiencyTier||0;
  state.lootingTier = p.lootingTier||0;
  state.blocksMined = p.blocksMined||0;
  state.seenVictory = !!p.seenVictory;
  state.maxDepthReached = p.maxDepthReached||0;
  state.inventory = { grass:0, dirt:0, stone:0, coal:0, iron:0, gold:0, emerald:0, diamond:0,
                       darkstone:0, coalDeep:0, ironDeep:0, goldDeep:0, emeraldDeep:0, diamondDeep:0, totem:0 };
  if(p.inventory) Object.assign(state.inventory, p.inventory);
  state.chestsOpened = p.chestsOpened || {};
  state.worldSeed = (typeof p.worldSeed==='number') ? p.worldSeed : 20261;
  state.minedTiles = Array.isArray(p.minedTiles) ? p.minedTiles : [];
  state.playerX = (typeof p.playerX==='number') ? p.playerX : null;
  state.playerY = (typeof p.playerY==='number') ? p.playerY : null;
  state.savedAt = p.savedAt||0;
}

function captureRuntimeIntoState(){
  state.playerX = player.x;
  state.playerY = player.y;
  state.minedTiles = Array.from(minedTilesSet);
  state.savedAt = Date.now();
}

// Writes the CURRENT in-memory state into one specific slot. Never touches other slots.
function saveToSlot(n){
  try{
    captureRuntimeIntoState();
    localStorage.setItem(slotKey(n), JSON.stringify(state));
    currentSlot = n;
    localStorage.setItem(LAST_SLOT_KEY, String(n));
    return true;
  }catch(e){
    console.error('saveToSlot failed', e);
    return false;
  }
}

// Background/event autosave: only ever writes to the slot the player explicitly chose
// (via "Salvar Aqui" or "Carregar"). A brand-new, never-saved session never touches any slot.
let saveTimer = 0;
function autoSave(){
  if(currentSlot) saveToSlot(currentSlot);
}

function getSlotMeta(n){
  try{
    const raw = localStorage.getItem(slotKey(n));
    if(!raw) return null;
    const p = JSON.parse(raw);
    const pick = PICKAXES[p.pickaxeTier]||PICKAXES[0];
    const depth = p.maxDepthReached||0;
    let phase = 'Montanha';
    if(depth>=PROFUNDEZAS_START_DEPTH) phase='Profundezas';
    else if(depth>=DEEP_START_DEPTH) phase='Pedra Escura';
    return { money:p.money||0, pickaxeName:pick.name.replace('Picareta de ',''), phase, savedAt:p.savedAt||0 };
  }catch(e){ return null; }
}

// Full load: parses a slot, applies it to `state`, rebuilds the world/chests and restores
// the player's position. Used by both "Continuar" and a slot's "Carregar" button.
function loadSlotIntoRuntime(n){
  try{
    const raw = localStorage.getItem(slotKey(n));
    if(!raw) return false;
    const p = JSON.parse(raw);
    applyLoadedStateObject(p);
    currentSlot = n;
    localStorage.setItem(LAST_SLOT_KEY, String(n));
    rand = mulberry32(state.worldSeed||20261);
    buildSurface();
    buildGrid();
    minedTilesSet = new Set(state.minedTiles||[]);
    applyMinedTiles();
    buildChests();
    if(typeof state.playerX==='number' && typeof state.playerY==='number'){
      player.x = state.playerX; player.y = state.playerY; player.vx=0; player.vy=0;
    } else {
      respawnAtSurface();
    }
    updateHUD();
    return true;
  }catch(e){
    console.error('loadSlotIntoRuntime failed', e);
    return false;
  }
}

function doSaveToSlot(n){
  const ok = saveToSlot(n);
  showToast(ok ? 'Jogo salvo com sucesso no Slot '+n+'!' : 'Falha ao salvar o jogo.');
  renderSlots();
}
function doLoadSlot(n){
  const ok = loadSlotIntoRuntime(n);
  if(!ok){ showToast('Não foi possível carregar esse slot.'); return; }
  closeOverlay('slots-overlay');
  closeOverlay('pause-overlay');
  document.getElementById('main-menu').style.display='none';
  gameStarted = true;
}
function doDeleteSlot(n){
  try{ localStorage.removeItem(slotKey(n)); }catch(e){}
  if(currentSlot===n) currentSlot=null;
  try{
    const last = localStorage.getItem(LAST_SLOT_KEY);
    if(last && Number(last)===n) localStorage.removeItem(LAST_SLOT_KEY);
  }catch(e){}
  showToast('Slot '+n+' excluído.');
  renderSlots();
}

function bagCapacity(){ return BAGS[state.bagTier].cap; }
function investmentMult(){ return INVESTMENTS[state.investmentTier].mult; }
function inventoryTotal(){ let t=0; for(const k in state.inventory) t+=state.inventory[k]; return t; }
function inventoryHasSpace(n){ return inventoryTotal()+n <= bagCapacity(); }
function playerUnlockTier(){ return PICKAXES[state.pickaxeTier].unlockTier; }
function playerSpeedMult(){ return PICKAXES[state.pickaxeTier].speedMult * EFFICIENCY_TIERS[state.efficiencyTier].mult; }
function playerLootQty(baseYield){ return (baseYield||1) + LOOTING_TIERS[state.lootingTier].extra; }

/* ============================================================
   WORLD GENERATION
   ============================================================ */
function mulberry32(seed){
  return function(){
    seed |= 0; seed = (seed+0x6D2B79F5)|0;
    let t = Math.imul(seed ^ (seed>>>15), 1|seed);
    t = (t + Math.imul(t ^ (t>>>7), 61|t)) ^ t;
    return ((t ^ (t>>>14))>>>0)/4294967296;
  };
}
let rand = mulberry32(20261);

let surfaceRow = new Array(COLS);
function buildSurface(){
  for(let c=0;c<COLS;c++){
    if(c < PLATFORM_COLS){
      surfaceRow[c] = TOP_ROW;
    } else {
      const t = (c-PLATFORM_COLS)/(COLS-PLATFORM_COLS-1);
      const slope = t*t*60;
      const rugged = Math.max(0, Math.sin(c*0.25)*1.2 + Math.sin(c*0.06)*3.0);
      let row = Math.round(TOP_ROW + slope + rugged);
      row = Math.max(TOP_ROW, Math.min(ROWS-8, row));
      surfaceRow[c] = row;
    }
  }
}
// buildSurface() is (re)invoked later, after the world seed is known (default, slot load, or new game).

function oreForDepth(depth, rnd){
  if(depth<=2) return B.DIRT;
  if(depth < DEEP_START_DEPTH){
    const roll = rnd();
    let pCoal = depth>3 ?0.10:0;
    let pIron = depth>10?0.075:0;
    let pGold = depth>20?0.05:0;
    let pEmer = depth>32?0.032:0;
    let pDia  = depth>44?0.02:0;
    let acc=0;
    if(roll<(acc+=pDia)) return B.DIAMOND;
    if(roll<(acc+=pEmer)) return B.EMERALD;
    if(roll<(acc+=pGold)) return B.GOLD;
    if(roll<(acc+=pIron)) return B.IRON;
    if(roll<(acc+=pCoal)) return B.COAL;
    return B.STONE;
  } else if(depth < PROFUNDEZAS_START_DEPTH){
    // Pedra Escura layer: progressively rarer/better deep ores the further into the layer you go
    const dd = depth - DEEP_START_DEPTH;
    const roll = rnd();
    let pCoal = 0.12;
    let pIron = dd>4 ?0.09 :0.02;
    let pGold = dd>14?0.055:0.012;
    let pEmer = dd>28?0.03 :0.006;
    let pDia  = dd>46?0.02 :0.003;
    let acc=0;
    if(roll<(acc+=pDia)) return B.DIAMOND_DEEP;
    if(roll<(acc+=pEmer)) return B.EMERALD_DEEP;
    if(roll<(acc+=pGold)) return B.GOLD_DEEP;
    if(roll<(acc+=pIron)) return B.IRON_DEEP;
    if(roll<(acc+=pCoal)) return B.COAL_DEEP;
    return B.DARKSTONE;
  } else {
    // Profundezas: the endgame layer. Generous ore chances (the reward here is bulk 3x yield, not rarity)
    const dd2 = depth - PROFUNDEZAS_START_DEPTH;
    const roll = rnd();
    let pCoal = 0.15;
    let pIron = dd2>5 ?0.11 :0.05;
    let pGold = dd2>15?0.07 :0.02;
    let pEmer = dd2>25?0.045:0.01;
    let pDia  = dd2>40?0.03 :0.006;
    let acc=0;
    if(roll<(acc+=pDia)) return B.PROF_DIAMOND;
    if(roll<(acc+=pEmer)) return B.PROF_EMERALD;
    if(roll<(acc+=pGold)) return B.PROF_GOLD;
    if(roll<(acc+=pIron)) return B.PROF_IRON;
    if(roll<(acc+=pCoal)) return B.PROF_COAL;
    return B.PROF_STONE;
  }
}

let grid = [];
let minedTilesSet = new Set(); // tracks every tile dug this session, for persistence across reloads
function markMined(col,row){
  grid[row][col] = B.EMPTY;
  minedTilesSet.add(col+','+row);
}
function applyMinedTiles(){
  for(const key of minedTilesSet){
    const [c,r] = key.split(',').map(Number);
    if(grid[r] && c>=0 && c<COLS) grid[r][c] = B.EMPTY;
  }
}
function buildGrid(){
  for(let r=0;r<ROWS;r++) grid[r] = new Array(COLS).fill(B.EMPTY);
  for(let c=0;c<COLS;c++){
    if(c < PLATFORM_COLS){
      for(let r=TOP_ROW; r<ROWS; r++) grid[r][c] = B.OBSIDIAN;
      continue;
    }
    const sr = surfaceRow[c];
    for(let r=0;r<ROWS;r++){
      if(r<sr) continue;
      if(r===ROWS-1){ grid[r][c]=B.BEDROCK; continue; }
      if(r===sr){ grid[r][c]=B.GRASS; continue; }
      const depth = r-sr;
      grid[r][c] = oreForDepth(depth, rand);
    }
  }
  for(let c=COLS-9;c<COLS-1;c++){
    for(let r=ROWS-11;r<ROWS-5;r++){
      grid[r][c] = B.EMPTY;
    }
  }
}
// buildGrid() is (re)invoked later, after the world seed is known (default, slot load, or new game).

function tileAt(col,row){
  if(row<0||row>=ROWS||col<0||col>=COLS) return B.BEDROCK;
  return grid[row][col];
}
function isSolid(col,row){ return tileAt(col,row)!==B.EMPTY; }
function isIndestructible(type){ const d=BLOCK_DATA[type]; return d && d.tier===Infinity; }
function isPedraEscura(type){ return PEDRA_ESCURA_BLOCK_IDS.has(type); }
function isProfundezas(type){ return PROFUNDEZAS_BLOCK_IDS.has(type); }

/* ============================================================
   CHESTS
   ============================================================ */
let CHESTS = [];
function buildChests(){
  const specs = [
    {fc:0.08, fr:0.10, totem:false}, {fc:0.18, fr:0.22, totem:false}, {fc:0.30, fr:0.16, totem:true },
    {fc:0.42, fr:0.35, totem:false}, {fc:0.55, fr:0.28, totem:false}, {fc:0.63, fr:0.55, totem:true },
    {fc:0.74, fr:0.42, totem:false}, {fc:0.85, fr:0.62, totem:false}, {fc:0.92, fr:0.20, totem:false},
    // Baús das Profundezas — mais raros, mais escuros, recompensas maiores, escondidos bem no fundo
    {fc:0.15, fr:0.94, totem:true,  deep:true}, {fc:0.40, fr:0.97, totem:false, deep:true},
    {fc:0.62, fr:0.93, totem:false, deep:true}, {fc:0.80, fr:0.98, totem:true,  deep:true}
  ];
  CHESTS = specs.map((s,i)=>{
    const col = PLATFORM_COLS + Math.floor(s.fc*(COLS-PLATFORM_COLS-4)) + 2;
    const sr = surfaceRow[Math.min(COLS-1,col)];
    const row = Math.min(ROWS-3, sr + 3 + Math.floor(s.fr*(ROWS-sr-8)));
    grid[row][col] = B.EMPTY;
    return { id:'chest'+i, col, row, isTotem:s.totem, deep:!!s.deep, opened: !!state.chestsOpened['chest'+i] };
  });
}
// buildChests() is (re)invoked later, after buildGrid(), once the world seed is known.

