let floatTexts = [];
let particles = [];
function addFloatText(x,y,text,color){ floatTexts.push({x,y,text,color,life:1.0}); }
function addParticles(x,y,color,count){
  for(let i=0;i<count;i++) particles.push({x,y,vx:(Math.random()-0.5)*140,vy:-Math.random()*160-40,life:1.0,color});
}
function showToast(msg, ms){
  const t = document.getElementById('toast');
  t.textContent = msg; t.classList.add('show');
  clearTimeout(showToast._timer);
  showToast._timer = setTimeout(()=>t.classList.remove('show'), ms||3000);
}

function tryMine(dt){
  const pcx=(player.x+player.w/2)/TILE, pcy=(player.y+player.h/2)/TILE;
  const targetCol = Math.floor(mouseWorld.x/TILE);
  const targetRow = Math.floor(mouseWorld.y/TILE);
  const dx=(targetCol+0.5)-pcx, dy=(targetRow+0.5)-pcy;
  const dist = Math.sqrt(dx*dx+dy*dy);

  const active = (isPointerDown||touchMineHeld);
  if(!active || dist>REACH){ mining=null; if(player.state==='mine') player.state='idle'; return; }

  const type = tileAt(targetCol,targetRow);
  if(type===B.EMPTY){ mining=null; return; }

  player.facing = dx>=0?1:-1;
  player.state = 'mine';

  const data = BLOCK_DATA[type];
  const key = targetCol+','+targetRow;

  if(data.tier===Infinity){
    if(!mining||mining.col!==targetCol||mining.row!==targetRow) mining={col:targetCol,row:targetRow,progress:0,blocked:true,reason:'indestructivel'};
    return;
  }
  if(playerUnlockTier() < data.tier){
    if(!mining||mining.col!==targetCol||mining.row!==targetRow){
      const needed = pickaxeNeededForTier(data.tier);
      mining={col:targetCol,row:targetRow,progress:0,blocked:true,reason:'tier',neededName:needed.name};
      if(lastTierToastKey!==key){ showToast(needed.name+' necessária.'); lastTierToastKey=key; }
    }
    return;
  }
  if(!inventoryHasSpace(1)){
    if(!mining||mining.col!==targetCol||mining.row!==targetRow) mining={col:targetCol,row:targetRow,progress:0,blocked:true,reason:'cheio'};
    return;
  }

  if(!mining||mining.col!==targetCol||mining.row!==targetRow) mining={col:targetCol,row:targetRow,progress:0,blocked:false};

  const timeNeeded = data.mineTime/playerSpeedMult();
  mining.progress += dt/timeNeeded;

  if(mining.progress>=1){
    markMined(targetCol, targetRow);
    claimedTiles.delete(key);
    state.blocksMined++;
    const wanted = playerLootQty(data.baseYield);
    const free = bagCapacity()-inventoryTotal();
    const give = Math.max(1, Math.min(wanted, free));
    state.inventory[data.key] = (state.inventory[data.key]||0)+give;
    addFloatText(targetCol*TILE+TILE/2, targetRow*TILE, '+'+give+' '+data.name, MATERIAL_META[data.key].color);
    addParticles(targetCol*TILE+TILE/2, targetRow*TILE+TILE/2, data.color, 10);
    mining = null;
    updateHUD();
    checkVictoryByPosition();
  }
}

/* ============================================================
   PHYSICS
   ============================================================ */
function rectVsGrid(x,y,w,h){
  const left=Math.floor(x/TILE), right=Math.floor((x+w)/TILE);
  const top=Math.floor(y/TILE), bottom=Math.floor((y+h)/TILE);
  for(let r=top;r<=bottom;r++) for(let c=left;c<=right;c++) if(isSolid(c,r)) return true;
  return false;
}

function updatePlayer(dt){
  const left = keys['ArrowLeft']||keys['KeyA']||touchLeft;
  const right = keys['ArrowRight']||keys['KeyD']||touchRight;
  const jumpPressed = keys['Space']||keys['ArrowUp']||keys['KeyW']||touchJumpQueued;

  let moving=false;
  if(mining && !mining.blocked){ player.vx *= 0.8; }
  else {
    if(left){ player.vx=-MOVE_SPEED; player.facing=-1; moving=true; }
    else if(right){ player.vx=MOVE_SPEED; player.facing=1; moving=true; }
    else player.vx=0;
  }

  if(jumpPressed && player.onGround){ player.vy=-JUMP_VELOCITY; player.onGround=false; }
  touchJumpQueued=false;

  player.vy += GRAVITY*dt;
  if(player.vy>1400) player.vy=1400;

  let nx = player.x+player.vx*dt;
  if(!rectVsGrid(nx,player.y,player.w,player.h)){ player.x=nx; }
  else{
    if(player.vx>0) player.x = Math.floor((nx+player.w)/TILE)*TILE - player.w - 0.01;
    else if(player.vx<0) player.x = Math.floor(nx/TILE+1)*TILE + 0.01;
    player.vx=0;
  }

  let ny = player.y+player.vy*dt;
  if(!rectVsGrid(player.x,ny,player.w,player.h)){ player.y=ny; player.onGround=false; }
  else{
    if(player.vy>0){ player.y=Math.floor((ny+player.h)/TILE)*TILE-player.h-0.01; player.onGround=true; }
    else if(player.vy<0){ player.y=Math.floor(ny/TILE+1)*TILE+0.01; }
    player.vy=0;
  }

  player.x = Math.max(TILE*0.2, Math.min(player.x, (COLS-1)*TILE-player.w));
  if(player.y > ROWS*TILE+300){ respawnAtSurface(); }

  if(!mining){ if(moving) player.state='walk'; else if(player.onGround) player.state='idle'; }
  if(moving) player.walkT += dt*9;
}

function checkVictoryByPosition(){
  const col = Math.floor((player.x+player.w/2)/TILE);
  const row = Math.floor((player.y+player.h)/TILE);
  if(col>=COLS-9 && row>=ROWS-10 && !state.seenVictory){
    state.seenVictory = true;
    document.getElementById('victory-money').textContent = state.money.toLocaleString('pt-BR');
    document.getElementById('victory-blocks').textContent = state.blocksMined.toLocaleString('pt-BR');
    openOverlay('victory-overlay');
    autoSave();
  }
}

/* ============================================================
   BASE STRUCTURES
   ============================================================ */
const bancada = { col:4, row:TOP_ROW };
const triturador = { col:9, row:TOP_ROW };
const machinesBancada = { col:13, row:TOP_ROW };
const enchantBancada = { col:17, row:TOP_ROW };

function distToTile(col,row){
  const pcx=(player.x+player.w/2)/TILE, pcy=(player.y+player.h/2)/TILE;
  const dx=pcx-(col+0.8), dy=pcy-row;
  return Math.sqrt(dx*dx+dy*dy);
}
function nearBancada(){ return distToTile(bancada.col,bancada.row) < INTERACT_REACH; }
function nearTriturador(){ return distToTile(triturador.col,triturador.row) < INTERACT_REACH; }
function nearMachines(){ return distToTile(machinesBancada.col,machinesBancada.row) < INTERACT_REACH; }
function nearEnchant(){ return distToTile(enchantBancada.col,enchantBancada.row) < INTERACT_REACH; }
function nearestChest(){
  let best=null, bestD=INTERACT_REACH;
  for(const c of CHESTS){
    if(c.opened) continue;
    const d = distToTile(c.col, c.row+1);
    if(d<bestD){ bestD=d; best=c; }
  }
  return best;
}

let anyOverlayOpen = false;
function openOverlay(id){ document.getElementById(id).style.display='flex'; anyOverlayOpen=true; }
function closeOverlay(id){ document.getElementById(id).style.display='none'; anyOverlayOpen = !!document.querySelector('.overlay[style*="flex"]'); }

function handleInteractKey(){
  if(!gameStarted || anyOverlayOpen) return;
  if(nearBancada()){ openShop(); return; }
  if(nearTriturador()){ openTriturador(); return; }
  if(nearMachines()){ openMachines(); return; }
  if(nearEnchant()){ openEnchant(); return; }
  const ch = nearestChest();
  if(ch){ openChest(ch); return; }
}

/* ---- shared row builder ---- */
function makeRow(cfg){
  const row = document.createElement('div');
  row.className='pick-row';
  if(cfg.isCurrent) row.classList.add('current');
  if(!cfg.owned && !cfg.isNext) row.classList.add('locked');

  const swatch = document.createElement('div');
  swatch.className='pick-swatch';
  swatch.style.background = cfg.swatchBg;
  if(cfg.iconKey && ICONS[cfg.iconKey]){
    const img = document.createElement('img');
    img.src = ICONS[cfg.iconKey];
    img.alt = '';
    swatch.appendChild(img);
  } else {
    swatch.textContent = cfg.swatchIcon||'';
  }
  row.appendChild(swatch);

  const info = document.createElement('div');
  info.className='pick-info';
  info.innerHTML = `<div class="name">${cfg.name}</div><div class="desc">${cfg.desc}</div>`;
  row.appendChild(info);

  const btn = document.createElement('button');
  btn.className='pick-buy';
  if(cfg.owned){
    btn.textContent = cfg.isCurrent ? 'EM USO' : 'OBTIDO';
    btn.disabled = true;
  } else if(cfg.isNext){
    btn.textContent = cfg.cost===0 ? 'PEGAR GRÁTIS' : 'COMPRAR R$'+cfg.cost.toLocaleString('pt-BR');
    btn.disabled = state.money < cfg.cost;
    btn.addEventListener('click', ()=>{
      if(state.money>=cfg.cost){
        state.money -= cfg.cost;
        cfg.onBuy();
        updateHUD(); cfg.rerender(); autoSave();
      }
    });
  } else {
    btn.textContent='BLOQUEADO';
    btn.disabled=true;
  }
  row.appendChild(btn);
  return row;
}

